  "dreamlist.m_earthquake": "Big change shaking your foundations; time to rebuild stronger.",
  "dreamlist.m_egg": "Potential and new life; something is about to hatch.",
  "dreamlist.m_ex": "Usually not about the person: a lesson or feeling from that time is resurfacing.",
  "dreamlist.m_exam": "Feeling judged or unprepared. Often a sign you care about doing well.",
  "dreamlist.m_falling": "Losing control or fear of failure. Find what you can hold on to.",
  "dreamlist.m_father": "Authority, protection and guidance.",
  "dreamlist.m_fire": "Passion, anger or transformation. Something in your life is changing fast.",
  "dreamlist.m_fish": "Ideas and opportunities from the deep; in folk tradition, good luck and blessing.",
  "dreamlist.m_flood": "Feeling overwhelmed by emotions or tasks.",
  "dreamlist.m_flower": "Beauty, love and things blooming in your life.",
  "dreamlist.m_flying": "Freedom and rising above a problem. You feel capable and light.",
  "dreamlist.m_food": "Nourishment — what feeds your body, mind or heart.",
  "dreamlist.m_forest": "The unconscious and the unknown; finding your own way.",
  "dreamlist.m_friend": "A quality you admire in that friend, or a need for connection.",
  "dreamlist.m_fruit": "The rewards of your efforts; ripe fruit: results are ready.",
  "dreamlist.m_funeral": "Letting go of the past — saying goodbye to a habit, a role or a chapter.",
  "dreamlist.m_garden": "Your inner world and what you cultivate; a well-kept garden means care paying off.",
  "dreamlist.m_ghost": "Unfinished business or memories that still visit you.",
  "dreamlist.m_gift": "Recognition, talent or a pleasant surprise coming.",
  "dreamlist.m_gold": "Something precious in you or your life; success that you earned.",
  "dreamlist.m_hair": "Strength and self-image. Cutting hair: a change you choose.",
  "dreamlist.m_horse": "Strength, freedom and drive. Riding well means you are in control of your path.",
  "dreamlist.m_house": "Yourself and your inner life. New rooms: new sides of you to discover.",
  "dreamlist.m_island": "The wish to rest or to be alone for a while.",
  "dreamlist.m_key": "A solution or an answer within reach.",
  "dreamlist.m_king": "Authority and self-worth; you may be ready to lead.",
  "dreamlist.m_kiss": "Affection, harmony and acceptance.",
  "dreamlist.m_knife": "Cutting ties or a sharp decision; also words that hurt.",
  "dreamlist.m_late": "Fear of missed chances or too much pressure.",
  "dreamlist.m_laughing": "Joy and relief; tension is easing.",
  "dreamlist.m_letter": "News or something unsaid that wants to be expressed.",
  "dreamlist.m_light": "Understanding and hope; an answer is near.",
  "dreamlist.m_lion": "Courage, pride and power. You may need to stand up for yourself.",
  "dreamlist.m_lost": "Uncertainty about your direction; a sign to pause and choose.",
  "dreamlist.m_milk": "Care, comfort and purity.",
  "dreamlist.m_mirror": "Self-reflection: how you see yourself and how you think others see you.",
  "dreamlist.m_money": "Self-worth and energy you give or receive. Finding money: an opportunity; losing it: worry about value.",
  "dreamlist.m_moon": "Intuition, cycles and the hidden side of things.",
  "dreamlist.m_mother": "Care, comfort and your own nurturing side.",
  "dreamlist.m_mountain": "A goal or a challenge. Reaching the top: achievement within reach.",
  "dreamlist.m_mouse": "Small worries that nibble at your peace.",
