  "ptest.chakra_r6": "Crown|Try a moment of gratitude, prayer or meditation each evening.",
  "ptest.dstyle_q1": "I compare pros and cons before I decide.",
  "ptest.dstyle_q2": "I look for facts and data.",
  "ptest.dstyle_q3": "I trust my gut feeling.",
  "ptest.dstyle_q4": "I often just know what is right.",
